I'll build this as a two-column surface: the four KPI tiles on one side and the year-over-year comparison chart on the other. The catalog has no generic container, so I'm using `columns` as the root.

<a2ui-json>
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "metrics-overview",
      "catalogId": "https://a2uicatalog.ai/catalog/c-data-display.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "metrics-overview",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 2,
          "gap": "1.5rem",
          "align": "top",
          "items": [
            {
              "blocks": [
                {
                  "id": "kpi-row",
                  "component": "metric_row",
                  "cols": 2,
                  "metrics": [
                    {
                      "value": "48,210",
                      "prefix": "$",
                      "label": "Revenue",
                      "sub": "vs. last month",
                      "trend": "up"
                    },
                    {
                      "value": "9,340",
                      "label": "Active users",
                      "sub": "vs. last month",
                      "trend": "up"
                    },
                    {
                      "value": "2.3",
                      "suffix": "%",
                      "label": "Churn rate",
                      "sub": "vs. last month",
                      "trend": "down"
                    },
                    {
                      "value": "212",
                      "suffix": " ms",
                      "label": "Avg response time",
                      "sub": "vs. last month",
                      "trend": "down"
                    }
                  ]
                }
              ]
            },
            {
              "blocks": [
                {
                  "id": "comparison-chart",
                  "component": "chartjs_bar",
                  "labels": ["Q1", "Q2", "Q3", "Q4"],
                  "datasets": [
                    {
                      "label": "This year",
                      "data": [32, 41, 38, 52]
                    },
                    {
                      "label": "Last year",
                      "data": [28, 35, 40, 44]
                    }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
</a2ui-json>

The KPI values and the chart data are placeholders. Replace them with real figures before use.
